<script setup>import {onMounted,reactive,ref} from 'vue';import api from '../api';import {useAuthStore} from '../stores/auth';import {ElMessage} from 'element-plus';const auth=useAuthStore(),list=ref([]),labs=ref([]),keyword=ref(''),status=ref(''),visible=ref(false),editing=ref(false);const empty=()=>({deviceCode:'',name:'',category:'计算机',model:'',labId:null,purchaseDate:'',status:'NORMAL',remark:''}),form=reactive(empty());const labels={NORMAL:'正常',FAULT:'故障',MAINTENANCE:'维修中',SCRAPPED:'已报废'},types={NORMAL:'success',FAULT:'danger',MAINTENANCE:'warning',SCRAPPED:'info'};async function load(){list.value=(await api.get('/devices',{params:{keyword:keyword.value||undefined,status:status.value||undefined}})).data}function open(r){Object.assign(form,r||empty());editing.value=!!r;visible.value=true}async function save(){if(editing.value)await api.put(`/manage/devices/${form.id}`,form);else await api.post('/manage/devices',form);visible.value=false;ElMessage.success('保存成功');await load()}onMounted(async()=>{labs.value=(await api.get('/labs')).data;await load()});</script>
<template><div class="page"><div class="page-head"><div><h2 class="page-title">设备台账</h2><div class="page-sub">集中维护设备归属、型号和运行状态</div></div><el-button v-if="auth.isManager" type="primary" @click="open()"><Plus/>新增设备</el-button></div><div class="panel"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="设备名称或编号" style="width:250px"/><el-select v-model="status" clearable placeholder="全部状态" style="width:140px"><el-option v-for="(v,k) in labels" :key="k" :label="v" :value="k"/></el-select><el-button @click="load">查询</el-button></div><el-table :data="list"><el-table-column prop="deviceCode" label="设备编号" width="150"/><el-table-column prop="name" label="设备名称" min-width="150"><template #default="s"><b>{{s.row.name}}</b></template></el-table-column><el-table-column prop="category" label="类别" width="110"/><el-table-column prop="model" label="型号" min-width="150"/><el-table-column prop="labName" label="所属实验室" min-width="150"/><el-table-column prop="purchaseDate" label="购置日期" width="120"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="types[s.row.status]">{{labels[s.row.status]}}</el-tag></template></el-table-column><el-table-column v-if="auth.isManager" label="操作" width="90"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑设备':'新增设备'" width="620"><el-form label-width="90px"><el-row :gutter="16"><el-col :span="12"><el-form-item label="设备编号"><el-input v-model="form.deviceCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="设备名称"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="设备类别"><el-input v-model="form.category"/></el-form-item></el-col><el-col :span="12"><el-form-item label="型号"><el-input v-model="form.model"/></el-form-item></el-col><el-col :span="12"><el-form-item label="所属实验室"><el-select v-model="form.labId"><el-option v-for="x in labs" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="设备状态"><el-select v-model="form.status"><el-option v-for="(v,k) in labels" :key="k" :label="v" :value="k"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="购置日期"><el-date-picker v-model="form.purchaseDate" value-format="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="24"><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
